<script>
  // scatter constellation nodes and connect nearby ones
  const portrait = document.getElementById('portrait');
  const svg = document.getElementById('links');
  const pts = [];
  // seeded pseudo-random for a stable portrait
  let seed = 42;
  function rnd() { seed = (seed * 16807) % 2147483647; return seed / 2147483647; }

  for (let i = 0; i < 46; i++) {
    const x = rnd() * 500, y = rnd() * 500;
    // keep the face area clear
    const dx = x - 250, dy = y - 250;
    if (Math.sqrt(dx*dx + dy*dy) < 175) { i--; continue; }
    pts.push([x, y]);
    const n = document.createElement('div');
    n.className = 'node';
    const s = 2 + rnd() * 3;
    n.style.cssText = `left:${x}px;top:${y}px;width:${s}px;height:${s}px;animation-delay:${rnd()*4}s`;
    portrait.appendChild(n);
  }

  for (let i = 0; i < pts.length; i++) {
    for (let j = i + 1; j < pts.length; j++) {
